'use strict';

// MODULES //

var zip2views1d = require( '@stdlib/ndarray/base/zip2views1d' );
var DataSet = require( '@stdlib/plot/vega/data/values' );


// MAIN //

/**
* Converts a list of one-dimensional ndarrays to a "tidy" data set.
*
* @param {ArrayLikeObject<ndarrayLike>} list - list of ndarrays
* @param {string} name - data set name
* @param {Array<string>} fields - list of field names
* @returns {DataSet} data set instance
*
* @example
* var array = require( '@stdlib/ndarray/array' );
*
* var x = array( [ 1, 2, 3 ] );
* var y = array( [ 4, 5, 6 ] );
*
* var v = vectors2tidy( [ x, y ], 'data', [ 'x', 'y' ] );
* // returns <DataSet>
*/
function vectors2tidy( list, name, fields ) {
	// TODO: add input argument validation

	return new DataSet({
		'name': name,
		'values': zip2views1d( list, fields )
	});
}


// EXPORTS //

module.exports = vectors2tidy;
